MARKER="/* P125_OBSERVER */"
def patch(source, edits):
    if MARKER in source:
        if source.count(MARKER)!=1 or any(source.count(new)!=1 for _,new in edits):
            raise ValueError("inconsistent P12.5 overlay")
        return source
    for old,new in edits:
        if source.count(old)!=1:
            raise ValueError("P12.5 pinned source anchor changed: "+old[:100])
        source=source.replace(old,new,1)
    return source
def apply(root):
    results={}
    for relative,edits in EDITS.items():
        path=root/relative
        results[path]=patch(path.read_text(encoding="utf-8"),edits)
    for path,source in results.items():
        path.write_text(source,encoding="utf-8")
    print("P12.5 timer source attribution: exact pinned anchors PASS")
if __name__=="__main__":
    apply(Path(sys.argv[1]))
